//! `jsnum.json` — `String(x)` and `JSON.stringify(x)` from real JavaScript.
//!
//! Generated by `xtask/vectors/jsnum.mjs`. This family predates the others and has
//! no upstream RxDB provenance: it pins the number-to-string conversion that index
//! strings, schema hashes and document serialisation all depend on.
//!
//! Vectors store the double as a *string*, so both sides parse identical bits and no
//! reader can lose precision in transit. `input` is therefore a string even though
//! it is conceptually a number, and non-finite values appear by name (`"NaN"`).

use serde::Deserialize;

use crate::FamilyFile;

/// The decoded `jsnum.json`.
#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Vectors {
    /// The documentation comment the generator wrote into the file.
    #[serde(rename = "$comment")]
    pub comment: String,
    /// The generator that wrote the file, e.g. `xtask/vectors/generate.mjs`.
    pub generator: String,
    /// Informational Node version; `--check` ignores it, so it may differ locally.
    pub node: String,
    /// Upstream RxDB version the vectors came from. Absent for `jsnum`, which only
    /// needs Node.
    #[serde(default, rename = "rxdbVersion")]
    pub rxdb_version: Option<String>,
    /// Upstream RxDB commit the vectors came from. Same condition as `rxdb_version`.
    #[serde(default, rename = "rxdbCommit")]
    pub rxdb_commit: Option<String>,
    /// The recorded conversion, e.g. `number->string`.
    pub format: String,
    /// One entry per distinct input value.
    pub cases: Vec<Case>,
}

impl FamilyFile for Vectors {
    fn provenance(&self) -> crate::Provenance {
        crate::Provenance {
            comment: self.comment.clone(),
            generator: self.generator.clone(),
            node: self.node.clone(),
            rxdb_version: self.rxdb_version.clone(),
            rxdb_commit: self.rxdb_commit.clone(),
        }
    }
}

impl Vectors {
    /// The provenance header of this file.
    ///
    /// Inherent rather than trait-only so a consumer can call it without importing
    /// [`FamilyFile`]; the trait exists for the loader's generic bound.
    pub fn provenance(&self) -> crate::Provenance {
        FamilyFile::provenance(self)
    }
}

/// One number and the two string forms JavaScript produced for it.
#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Case {
    /// The canonical shortest round-trip decimal, as a string.
    ///
    /// `"-0"`, `"NaN"`, `"Infinity"` and `"-Infinity"` appear literally; parse
    /// those specially rather than with `str::parse::<f64>`, which handles `NaN`
    /// but not the signed-zero spelling as a distinct value.
    pub input: String,
    /// `String(input)`.
    #[serde(rename = "jsString")]
    pub js_string: String,
    /// `JSON.stringify(input)`.
    #[serde(rename = "jsJson")]
    pub js_json: String,
}

impl Case {
    /// Parse [`Case::input`] into the `f64` whose formatting is being asserted.
    pub fn parse_input(&self) -> Option<f64> {
        match self.input.as_str() {
            "NaN" => Some(f64::NAN),
            "Infinity" => Some(f64::INFINITY),
            "-Infinity" => Some(f64::NEG_INFINITY),
            "-0" => Some(-0.0),
            other => other.parse().ok(),
        }
    }
}
